"""Strict, deterministic generation of the factory's supported Bundle Jobs."""

from __future__ import annotations

import argparse
import copy
import difflib
import json
import sys
from pathlib import Path
from typing import Any

import yaml
from jsonschema import Draft202012Validator
from yaml.resolver import BaseResolver

REPO_ROOT = Path(__file__).resolve().parents[2]
SCHEMA_PATH = Path(__file__).with_name("schemas") / "job-v1.schema.json"
GENERATED_HEADER = (
    "# Generated by python -m tools.bundle_generator.\n"
    "# Source: specs/jobs.yml. Do not edit this file manually.\n"
)
SUPPORTED_PROFILE = "classic_single_user_small"
RESERVED_CLUSTER_TAGS = {"domain", "capability", "environment", "managed_by", "generated_by"}


class SpecError(ValueError):
    """A spec is syntactically valid YAML but violates the factory contract."""


class UniqueKeyLoader(yaml.SafeLoader):
    """Safe YAML loader that rejects duplicate mapping keys."""


def _construct_unique_mapping(
    loader: UniqueKeyLoader, node: yaml.MappingNode, deep: bool = False
) -> dict[str, Any]:
    mapping: dict[str, Any] = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if key in mapping:
            raise SpecError(f"duplicate YAML key {key!r} at line {key_node.start_mark.line + 1}")
        mapping[key] = loader.construct_object(value_node, deep=deep)
    return mapping


UniqueKeyLoader.add_constructor(
    BaseResolver.DEFAULT_MAPPING_TAG,
    _construct_unique_mapping,
)


def load_yaml(path: Path) -> dict[str, Any]:
    """Load trusted structure without allowing Python-specific YAML objects."""
    try:
        loaded = yaml.load(path.read_text(encoding="utf-8"), Loader=UniqueKeyLoader)
    except yaml.YAMLError as exc:
        raise SpecError(f"{path}: invalid YAML: {exc}") from exc
    if not isinstance(loaded, dict):
        raise SpecError(f"{path}: the document root must be a mapping")
    return loaded


def _json_path(parts: Any) -> str:
    return "$" + "".join(f"[{part}]" if isinstance(part, int) else f".{part}" for part in parts)


def validate_spec(spec: dict[str, Any], source: Path) -> None:
    """Apply JSON Schema plus cross-reference and DAG checks."""
    schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
    errors = sorted(
        Draft202012Validator(schema).iter_errors(spec),
        key=lambda error: [str(part) for part in error.absolute_path],
    )
    if errors:
        details = "; ".join(
            f"{_json_path(error.absolute_path)}: {error.message}" for error in errors
        )
        raise SpecError(f"{source}: schema validation failed: {details}")

    job_keys: set[str] = set()
    for job in spec["jobs"]:
        if job["key"] in job_keys:
            raise SpecError(f"{source}: duplicate job key {job['key']!r}")
        job_keys.add(job["key"])

        cluster_keys = [cluster["key"] for cluster in job["clusters"]]
        if len(cluster_keys) != len(set(cluster_keys)):
            raise SpecError(f"{source}: job {job['key']!r} has duplicate cluster keys")
        task_keys = [task["key"] for task in job["tasks"]]
        if len(task_keys) != len(set(task_keys)):
            raise SpecError(f"{source}: job {job['key']!r} has duplicate task keys")

        for cluster in job["clusters"]:
            reserved = RESERVED_CLUSTER_TAGS.intersection(cluster["tags"])
            if reserved:
                raise SpecError(
                    f"{source}: cluster {cluster['key']!r} overrides reserved tags: "
                    f"{', '.join(sorted(reserved))}"
                )
        tasks = {task["key"]: task for task in job["tasks"]}
        for task in job["tasks"]:
            if task["cluster_key"] not in cluster_keys:
                raise SpecError(
                    f"{source}: task {task['key']!r} references unknown cluster "
                    f"{task['cluster_key']!r}"
                )
            for dependency in task.get("depends_on", []):
                if dependency not in tasks:
                    raise SpecError(
                        f"{source}: task {task['key']!r} depends on unknown task {dependency!r}"
                    )

        visiting: set[str] = set()
        visited: set[str] = set()

        def visit(
            task_key: str,
            tasks: dict[str, Any] = tasks,
            visiting: set[str] = visiting,
            visited: set[str] = visited,
        ) -> None:
            if task_key in visiting:
                raise SpecError(f"{source}: dependency cycle detected at {task_key!r}")
            if task_key in visited:
                return
            visiting.add(task_key)
            for dependency in tasks[task_key].get("depends_on", []):
                visit(dependency)
            visiting.remove(task_key)
            visited.add(task_key)

        for task_key in tasks:
            visit(task_key)


def _build_cluster(metadata: dict[str, str], cluster: dict[str, Any]) -> dict[str, Any]:
    if cluster["profile"] != SUPPORTED_PROFILE:
        raise SpecError(f"unsupported compute profile {cluster['profile']!r}")
    custom_tags = {
        "domain": metadata["domain"],
        "capability": metadata["capability"],
        "environment": "${bundle.target}",
        **cluster["tags"],
        "managed_by": "bundle",
        "generated_by": "bundle",
    }
    return {
        "job_cluster_key": cluster["key"],
        "new_cluster": {
            "policy_id": "${var.policy_id}",
            "spark_version": "${var.spark_version}",
            "node_type_id": "${var.node_type_id}",
            "data_security_mode": "SINGLE_USER",
            "num_workers": 1,
            "custom_tags": custom_tags,
        },
    }


def _build_task(package: dict[str, str], task: dict[str, Any]) -> dict[str, Any]:
    generated: dict[str, Any] = {"task_key": task["key"]}
    if task.get("depends_on"):
        generated["depends_on"] = [{"task_key": dependency} for dependency in task["depends_on"]]
    generated["job_cluster_key"] = task["cluster_key"]
    generated["timeout_seconds"] = task["timeout_seconds"]
    generated.update(copy.deepcopy(task["retry"]))
    generated["python_wheel_task"] = {
        "package_name": package["name"],
        "entry_point": task["wheel"]["entry_point"],
        "named_parameters": copy.deepcopy(task["wheel"]["named_parameters"]),
    }
    generated["libraries"] = [{"whl": package["wheel_path"]}]
    return generated


def build_resource(spec: dict[str, Any]) -> dict[str, Any]:
    """Translate the validated v1 contract to native Bundle resource mappings."""
    metadata = spec["metadata"]
    jobs: dict[str, Any] = {}
    for job in spec["jobs"]:
        jobs[job["key"]] = {
            "name": job["name"],
            "max_concurrent_runs": job["max_concurrent_runs"],
            "parameters": [
                {"name": name, "default": value} for name, value in job["parameters"].items()
            ],
            "tags": {
                "domain": metadata["domain"],
                "capability": metadata["capability"],
                "environment": "${bundle.target}",
                "layer": job["layer"],
                "managed_by": "bundle",
            },
            "job_clusters": [_build_cluster(metadata, cluster) for cluster in job["clusters"]],
            "tasks": [_build_task(spec["package"], task) for task in job["tasks"]],
        }
    return {"resources": {"jobs": jobs}}


def render_spec(spec_path: Path) -> str:
    spec = load_yaml(spec_path)
    validate_spec(spec, spec_path)
    body = yaml.safe_dump(
        build_resource(spec),
        sort_keys=False,
        allow_unicode=True,
        default_flow_style=False,
        width=1000,
    )
    return GENERATED_HEADER + body


def output_path_for(spec_path: Path) -> Path:
    domains_root = (REPO_ROOT / "domains").resolve()
    try:
        spec_path.resolve().relative_to(domains_root)
    except ValueError as exc:
        raise SpecError(f"{spec_path}: spec must live under {domains_root}") from exc
    capability_root = spec_path.parent.parent
    if spec_path.name != "jobs.yml" or spec_path.parent.name != "specs":
        raise SpecError(f"{spec_path}: expected <capability>/specs/jobs.yml")
    return capability_root / "resources" / "jobs.generated.yml"


def compare_output(output_path: Path, rendered: str) -> tuple[bool, str]:
    if not output_path.exists():
        return False, f"missing generated file: {output_path}"
    current = output_path.read_text(encoding="utf-8")
    if current == rendered:
        return True, ""
    diff = "".join(
        difflib.unified_diff(
            current.splitlines(keepends=True),
            rendered.splitlines(keepends=True),
            fromfile=str(output_path),
            tofile="expected-from-spec",
        )
    )
    return False, diff


def discover_specs() -> list[Path]:
    return sorted(REPO_ROOT.glob("domains/*/capabilities/*/specs/jobs.yml"))


def generate(spec_path: Path, check: bool) -> bool:
    spec_path = spec_path.resolve()
    rendered = render_spec(spec_path)
    output_path = output_path_for(spec_path)
    if check:
        matches, details = compare_output(output_path, rendered)
        if not matches:
            print(details, file=sys.stderr)
            return False
        print(f"OK: {output_path.relative_to(REPO_ROOT)}")
        return True
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(rendered, encoding="utf-8", newline="\n")
    print(f"generated: {output_path.relative_to(REPO_ROOT)}")
    return True


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="python -m tools.bundle_generator")
    subparsers = parser.add_subparsers(dest="command", required=True)
    generate_parser = subparsers.add_parser("generate")
    source = generate_parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--spec", type=Path)
    source.add_argument("--all", action="store_true")
    generate_parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)

    specs = discover_specs() if args.all else [args.spec]
    if not specs:
        print("ERROR: no specs found", file=sys.stderr)
        return 1
    try:
        results = [generate(spec_path, args.check) for spec_path in specs]
    except SpecError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1
    return 0 if all(results) else 1
